INSERT INTO `product` (`id`, `shelf_id`, `name`, `category`, `price`, `stock`, `status`, `description`, `image_url`, `back_image_url`, `side_image_url`, `showroom_stage`, `color_hex`) VALUES
(1, 6, 'iPhone 16 Pro Max 256GB 暗夜黑', '手机数码', 9999.00, 50, 'ON_SHELF', 'A18 Pro 芯片，超视网膜 XDR 屏，钛金属机身，支持 25W 无线快充与 7 天无理由退货。', NULL, NULL, NULL, 'STORE_GENERAL', '#C8C3F2'),
(2, 2, 'Sony WH-1000XM5 无线降噪头戴耳机', '数码影音', 2299.00, 30, 'ON_SHELF', '双芯驱动旗舰降噪，30小时超长续航，支持 LDAC 高清音频传输，一年全国联保。', NULL, NULL, NULL, 'STORE_GENERAL', '#A3D3EB'),
(3, 3, '客制化三模机械键盘 87键 RGB', '电脑外设', 499.00, 100, 'ON_SHELF', '热插拔轴座，Gasket 结构，全键无冲，PBT 双色键帽，支持蓝牙/2.4G/有线三模。', NULL, NULL, NULL, 'STORE_GENERAL', '#A8E6CF'),
(4, 4, 'Apple Watch Series 10 智能手表', '智能穿戴', 3199.00, 20, 'ON_SHELF', '全天候视网膜显示屏，ECG 心电图检测，50米深度防水，支持快速充电与体温感应。', NULL, NULL, NULL, 'STORE_GENERAL', '#DDD9FB'),
(5, 5, '4K 144Hz Mini-LED 电竞显示器 27英寸', '电脑办公', 2799.00, 15, 'ON_SHELF', '1152 分区背光，HDR1000 认证，1ms 极速响应，支持 Type-C 90W 反向供电。', NULL, NULL, NULL, 'STORE_GENERAL', '#00F0FF'),
(6, 7, '特仑苏有机全脂纯牛奶 250ml*12盒', '乳品冷饮', 68.00, 80, 'ON_SHELF', '优质乳蛋白 3.8g/100ml，原生高钙，天然有机牧场奶源。', NULL, NULL, NULL, 'STORE_GENERAL', '#EFEBE2'),
(7, 1, '烟台红富士苹果 净重5斤特级果', '生鲜果蔬', 39.90, 60, 'ON_SHELF', '产地直采，脆甜多汁，果香浓郁，冷链新鲜直达。', NULL, NULL, NULL, 'STORE_GENERAL', '#B05139'),
(101, 8, 'Heavyweight tee · Bone', '高定服饰', 48.00, 18, 'ON_SHELF', '240 gsm organic cotton with a tonal DHxWHY embroidery on the chest.', 'https://cdn.21st.dev/assets/mirror/14/1485bf44725b18fcdba71bfae54d67d648ab3bff4b24215a042c0cc4c895a2e6.webp', 'https://cdn.21st.dev/assets/mirror/69/69937e656430ae33d950303e0d53051273e5b02189750ef1e7429ec4bbf95e20.webp', 'https://cdn.21st.dev/assets/mirror/83/838468c32f16b4acba62e4601276737411156052444712ff2534fefe994a7bed.webp', 'STAGE_RAIL', '#EFEBE2'),
(102, 8, 'Graphic tee · CCgather', '高定服饰', 52.00, 16, 'ON_SHELF', 'Black tee with the CCgather wordmark printed front and back.', 'https://cdn.21st.dev/assets/mirror/d7/d769f183472d0fd98a7aff2a643593748cd36ef9da1497d9bf6f0d87d1025a9b.webp', 'https://cdn.21st.dev/assets/mirror/fe/fec6f7e96b198cc5b9aad333ca2c4c10968a746d87f6dc11d9c118607b509058.webp', 'https://cdn.21st.dev/assets/mirror/b3/b3b6984ea94b8b8cd19fb15387e89dca457ac0f947115c2a54a33217e4fb4571.webp', 'STAGE_RAIL', '#101214'),
(103, 8, 'Oxford shirt · Sky', '高定服饰', 74.00, 14, 'ON_SHELF', 'Pale sky oxford with a button-down collar and a tiny Maestiq embroidery.', 'https://cdn.21st.dev/assets/mirror/47/470a7723cef068f81e8a4c09d1ab3f8630c61b734c2168b10f3858e45efbf31f.webp', 'https://cdn.21st.dev/assets/mirror/9b/9be14e5dce879756775677e2d82dadc2ad9a1690b7df2f82de360cb3600d0ee5.webp', 'https://cdn.21st.dev/assets/mirror/59/5984d5ca60fd1aeee7e688ec33c2219a1c537fcde90d2accab813c13985f8632.webp', 'STAGE_RAIL', '#A3D3EB'),
(104, 8, 'Knit cardigan · Olive', '高定服饰', 96.00, 12, 'ON_SHELF', 'Chunky olive wool cardigan with wooden buttons and ribbed trims.', 'https://cdn.21st.dev/assets/mirror/58/581b13c5ca241c653dc94d2c8048c92a60f022cfbaaf153261076d3a6655827e.webp', 'https://cdn.21st.dev/assets/mirror/d9/d9178d906d37268565cf10af3431aee543aacfc73610f7fa7b0fa4758c498cb3.webp', 'https://cdn.21st.dev/assets/mirror/de/dee1c529600e0460413f1a9b07a29bedb7ea7dc96181fce5d9d6501231e6e45d.webp', 'STAGE_RAIL', '#758151'),
(105, 8, 'Hoodie · Maestiq', '高定服饰', 88.00, 15, 'ON_SHELF', 'Heather fleece hoodie with the Maestiq wordmark across the chest.', 'https://cdn.21st.dev/assets/mirror/51/51750ba098dd622df46695bca781b3f0ec336a36b93b070e638cc04455def6d6.webp', 'https://cdn.21st.dev/assets/mirror/e7/e75c4ac8fb7f14caae756338a31f81f1437bb312b78e0d7d906e9f956e7968fa.webp', 'https://cdn.21st.dev/assets/mirror/a2/a2eb2463d52146c341ede6bb9f6067e917a23eb29b7b1d1d4c40ac084a01c7ce.webp', 'STAGE_RAIL', '#A0A5AB'),
(106, 8, 'Crewneck sweatshirt · Lilac', '高定服饰', 78.00, 18, 'ON_SHELF', 'Muted lilac fleece crewneck with a raised DHxWHY puff print.', 'https://cdn.21st.dev/assets/mirror/8e/8e38660e2add9637c27846d9b8d620f2abb228a5a153ccfd7b1c808b6845e1f8.webp', 'https://cdn.21st.dev/assets/mirror/b9/b9214a6e009ce4b3044595a51ea010c299135bab5b26775c43d7175c86e77898.webp', 'https://cdn.21st.dev/assets/mirror/59/591872e42b483c43c1cd08a3ac4d7d40c0b5fa2bc585a36096faded2e696e84e.webp', 'STAGE_RAIL', '#CCB2E0'),
(107, 8, 'Piqué polo · Forest', '高定服饰', 62.00, 20, 'ON_SHELF', 'Forest piqué polo with a bone CCgather embroidery on the chest.', 'https://cdn.21st.dev/assets/mirror/19/19fe43cb681195ae227e3164088d86a07a1b6e33cc54c6e35637374736a16894.webp', 'https://cdn.21st.dev/assets/mirror/e0/e095182b1a7f04e600c5662aa871b4c055c294b152586817d84e312c22f744cf.webp', 'https://cdn.21st.dev/assets/mirror/00/005a8e10be234bc40917f3153208b8196ba1610c53c987e39942da1f4a7cd808.webp', 'STAGE_RAIL', '#185B37'),
(108, 8, 'Henley · Brick', '高定服饰', 56.00, 17, 'ON_SHELF', 'Dusty brick henley with a three-button placket, worn in from day one.', 'https://cdn.21st.dev/assets/mirror/84/84aa4b0e21ed11fcbc083647a607b94ee3a6c21cb66c114cfb1dad0792c15499.webp', 'https://cdn.21st.dev/assets/mirror/01/01c299df56a29afca8dad4a64858bd506667338bfbd0435118e6c3698c7881b3.webp', 'https://cdn.21st.dev/assets/mirror/9c/9ca38eeb156aae7d199d3c1ffb7947e395f77d1f094eea006c1b5fbb22352b4e.webp', 'STAGE_RAIL', '#B05139'),
(109, 8, 'Breton long sleeve', '高定服饰', 58.00, 15, 'ON_SHELF', 'Classic ink-and-bone Breton stripe with a boat neck.', 'https://cdn.21st.dev/assets/mirror/09/096002a95aba7de9c197de4cb5c78cbbe17c1677b19c547cc20c6dbef47a899c.webp', 'https://cdn.21st.dev/assets/mirror/74/74408a7dbb4f4fc6761ebb8d6ed93187248cddf75e1c2e70d38d04dfdd328776.webp', 'https://cdn.21st.dev/assets/mirror/ed/eda3afca537071a80d7d82b3f0d1055b56f1f3263c20772224bae6660bf4072c.webp', 'STAGE_RAIL', '#E4DFD3'),
(110, 8, 'Oversized tee · CCgather', '高定服饰', 52.00, 19, 'ON_SHELF', 'Boxy ochre tee with a small chest mark and a large CCgather back print.', 'https://cdn.21st.dev/assets/mirror/72/7208c811f54e123dd7b1a5c1c3926f43ca832f6c4c20c45de10671ffd544409d.webp', 'https://cdn.21st.dev/assets/mirror/d3/d356989b7bc741c5cfc934cac34983dfb24d5d6a6b6e7b8b7f6b27cd3eceae69.webp', 'https://cdn.21st.dev/assets/mirror/bf/bf94beeafb21f9cb21aa45057a67dc8a2e23ba95c7ac0f79dd27ba3ce4a1230c.webp', 'STAGE_RAIL', '#DE9C31'),
(201, 9, 'Samsung Galaxy S22 Ultra · Burgundy', '手机数码', 8999.00, 14, 'ON_SHELF', 'Built-in S Pen flagship with 108MP pro-grade quad camera system, Armor Aluminum frame, and Dynamic AMOLED 2X.', '/products/samsung-s22-ultra.png', '/products/samsung-s22-ultra.png', NULL, 'STAGE_TECH', '#00F0FF'),
(202, 9, 'HUAWEI Mate RS · Porsche Design', '手机数码', 9999.00, 8, 'ON_SHELF', 'Aerospace-cooled microcapsule PCM chassis with Leica triple optics and dual in-screen fingerprint architecture.', '/products/huawei-mate-rs.jpg', '/products/huawei-mate-rs.jpg', NULL, 'STAGE_TECH', '#FF2A54'),
(203, 9, 'Apple iPhone 12 · Mint Edition', '手机数码', 5499.00, 16, 'ON_SHELF', 'Ceramic Shield front glass with aerospace-grade aluminum edges, A14 Bionic neural engine, and Super Retina XDR.', '/products/iphone-12-mint.png', '/products/iphone-12-mint.png', NULL, 'STAGE_TECH', '#A8E6CF'),
(204, 9, 'DJI Mavic 3 Enterprise · RTK Drone', '航拍数码', 23800.00, 5, 'ON_SHELF', '4/3 CMOS Hasselblad wide camera with 56× hybrid zoom tele lens, omnidirectional obstacle sensing, and RTK module.', '/products/dji-mavic-3.png', '/products/dji-mavic-3.png', NULL, 'STAGE_TECH', '#FFA500'),
(205, 9, 'DJI Osmo Mobile · 3-Axis Gimbal', '影像配件', 999.00, 22, 'ON_SHELF', 'Foldable magnetic 3-axis smartphone stabilizer with built-in extension rod, ActiveTrack 6.0, and ShotGuides.', '/products/dji-osmo-mobile.png', '/products/dji-osmo-mobile.png', NULL, 'STAGE_TECH', '#C8C3F2'),
(301, 10, '贵州茅台酒 · 飞天典藏 500ml', '典藏名酒', 2799.00, 10, 'ON_SHELF', '核心产区坤沙大曲酱香工艺，五年陶坛陈酿勾调，乳白避光瓷瓶配经典飞天飘带礼盒。', '/products/moutai-feitian.jpg', '/products/moutai-feitian.jpg', NULL, 'STAGE_VITRINE', '#A8E6CF'),
(302, 10, '五粮液 · 52度水晶礼盒纪念酒', '典藏名酒', 1399.00, 8, 'ON_SHELF', '五种粮食古法包包曲酿造，高透多面切割亚克力水晶防尘礼盒封装，窖香浓郁回甘。', '/products/wuliangye-crystal.jpg', '/products/wuliangye-crystal.jpg', NULL, 'STAGE_VITRINE', '#C8C3F2'),
(303, 10, 'Beringer · 贝灵哲私家珍藏赤霞珠干红', '典藏名酒', 1680.00, 6, 'ON_SHELF', '纳帕谷百年名庄私家珍藏（Private Reserve），法国全新橡木桶陈酿 20 个月，深邃黑醋栗与雪松单宁。', '/products/beringer-reserve.jpg', '/products/beringer-reserve.jpg', NULL, 'STAGE_VITRINE', '#DDD9FB'),
(304, 10, 'Briar Artisan · 石楠木手工弯式烟斗', '典藏器物', 3280.00, 5, 'ON_SHELF', '地中海百年老根石楠木火焰纹手工打磨，纯银戒圈配手工硫化硬胶咬嘴与真皮礼盒。', '/products/briar-pipe.jpg', '/products/briar-pipe.jpg', NULL, 'STAGE_VITRINE', '#DE9C31'),
(305, 10, 'Mavic 3 Enterprise · 航测典藏套装', '典藏器物', 25999.00, 4, 'ON_SHELF', '配备 RTK 厘米级高精度定位模块与哈苏 4/3 CMOS 广角镜头，博物馆级独立恒温防尘柜陈列。', '/products/dji-mavic-3.png', '/products/dji-mavic-3.png', NULL, 'STAGE_VITRINE', '#00F0FF'),
(306, 10, 'Porsche Design · 徕卡三摄限量典藏版', '典藏器物', 12999.00, 3, 'ON_SHELF', '保时捷设计工作室联名流线超跑八曲面机身，航空级微胶囊散热与徕卡三摄光学模组。', '/products/huawei-mate-rs.jpg', '/products/huawei-mate-rs.jpg', NULL, 'STAGE_VITRINE', '#00FF66')
